// Default logos for downloadable MCP packages, embedded as data URIs (icon-only, no wordmark).
// Source: the user's vault (Anexos/Logos/Atlassian), the Atlassian brand icon set.
// Keyed by the "logo" id a package's manifest names; unknown ids fall back to a generic icon.

export const DEFAULT_MCP_LOGOS: Record<string, string> = {
  atlassian: "data:image/png;base64,",
  assets: "data:image/png;base64,",
  jira: "data:image/png;base64,",
  bitbucket: "data:image/png;base64,",
  confluence: "data:image/png;base64,",
  jsm: "data:image/png;base64,",
  admin: "data:image/png;base64,",
  trello: "data:image/png;base64,",
  csm: "data:image/png;base64,",
  automation: "data:image/png;base64,",
};

/** The bundled logo for a package's `logo` id, or "" (generic icon) when there is none. */
export function defaultLogoFor(id: string): string {
  return DEFAULT_MCP_LOGOS[id] ?? "";
}
